/**
 * The one place that owns this installation's ChatGPT credential state.
 *
 * Two concerns meet here and nowhere else: which account is active, and whether
 * its access token is still usable. The active account is persisted locally;
 * refreshes share one in-flight promise per authorization, because callers must
 * never refresh the same grant twice —
 * a refresh rotates the refresh token, so a second refresh using the old one is
 * refused and would look like a dead credential rather than a race.
 *
 * The remote surface reads account *facts* from here (email, plan, expiry) and
 * never a token.
 *
 * @module dsh-plugin-chatgpt-subscription/auth/manager
 */

import { openSync, closeSync, unlinkSync, mkdirSync, statSync } from 'node:fs'
import { dirname, join } from 'node:path'
import { randomUUID } from 'node:crypto'
import { ensureHostId } from './host-id.ts'
import { beginSignIn, type SignInAttempt, type SignInOptions } from './sign-in.ts'
import { refreshCredential, RefreshRefusedError } from './refresh.ts'
import { withCredentialFileLock } from './file-lock.ts'
import {
  emptyDocument, readDocument, writeDocument, type ChatGptStoreDocument,
} from './store.ts'
import { canSpendPlan, isFresh, isReplayNamespace, type ChatGptCredential } from './credential.ts'
import type { ChatGptRegistration } from './store.ts'
import { revokeGrant, type RevocationResult, type RevokeOptions } from './revoke.ts'

class StorageBusyError extends Error {}

/** What the UI may know about this installation's ChatGPT access. */
export interface ChatGptStatus {
  /** Whether at least one account is authorized and can spend its plan. */
  signedIn: boolean
  /** Whether a grant exists but the plan-usage scope was not granted. */
  planUsageDenied: boolean
  /** The active account's email, when known. */
  email?: string
  /** The active account's ChatGPT plan name, when known. */
  plan?: string
  /** When the active access token stops being usable, epoch milliseconds. */
  expiresAt?: number
  /** Local account keys (normally ID-token subjects), never used as replay identities. */
  accounts: { subject: string, email?: string, active: boolean }[]
}

/** Options for {@link ChatGptAuth}. */
export interface ChatGptAuthOptions {
  /** The directory this installation's state lives in. */
  stateDir: string
  /** The app name the human sees on the consent screen. */
  agentNameHint: string
  /** Endpoint overrides (tests). */
  endpoints?: {
    authorizeUrl?: string
    tokenUrl?: string
    preferredPort?: number
    /** Test-only signature verifier for synthetic issuer fixtures. */
    verifyIdTokenSignature?: SignInOptions['verifyIdTokenSignature']
    /** Override the revocation endpoint. */
    revocationEndpoint?: string
    /** Override the discovery document that names the revocation endpoint. */
    discoveryUrl?: string
  }
}

/**
 * Owns the stored grants, one active account, and the sign-in attempts in
 * flight.
 */
export class ChatGptAuth {
  private readonly file: string
  private readonly options: ChatGptAuthOptions
  private document: ChatGptStoreDocument | undefined
  private readonly refreshing = new Map<string, Promise<ChatGptCredential>>()

  /**
   * @param options - where state lives and what to call this app.
   */
  constructor(options: ChatGptAuthOptions) {
    this.options = options
    this.file = join(options.stateDir, 'chatgpt-auth.json')
  }

  /** The absolute path of the credential file, for diagnostics. */
  get storePath(): string {
    return this.file
  }

  private mutationLocked = false

  /** Serialize short storage transactions separately from the network refresh lock.
   * Synchronous callers fail promptly on contention instead of blocking the event loop. */
  private mutate<T>(task: () => T): T {
    if (this.mutationLocked) return task()
    mkdirSync(dirname(this.file), { recursive: true, mode: 0o700 })
    const lock = `${this.file}.lock`
    let handle: number
    try { handle = openSync(lock, 'wx', 0o600) } catch (error) {
      if ((error as NodeJS.ErrnoException).code !== 'EEXIST') throw error
      // Storage transactions contain no awaits; a two-minute lock is abandoned.
      try {
        if (Date.now() - statSync(lock).mtimeMs > 120_000) unlinkSync(lock)
      } catch (staleError) {
        if ((staleError as NodeJS.ErrnoException).code !== 'ENOENT') throw staleError
      }
      try { handle = openSync(lock, 'wx', 0o600) } catch (retryError) {
        if ((retryError as NodeJS.ErrnoException).code !== 'EEXIST') throw retryError
        throw new StorageBusyError('ChatGPT credentials are being updated; retry the account operation shortly')
      }
    }
    this.mutationLocked = true
    try { return task() } finally {
      this.mutationLocked = false
      closeSync(handle)
      unlinkSync(lock)
    }
  }

  /** Wait for short cross-process transactions without blocking their event loop.
   * After rotation succeeds, retain that result here until it is committed: the
   * old refresh token has already been consumed and must never be exchanged again. */
  private async mutateAsync<T>(task: () => T, signal?: AbortSignal): Promise<T> {
    for (;;) {
      signal?.throwIfAborted()
      try { return this.mutate(task) } catch (error) {
        if (!(error instanceof StorageBusyError)) throw error
        await new Promise<void>(resolve => setTimeout(resolve, 20))
      }
    }
  }

  /** Load lazily so a plugin that is never used never touches the disk. */
  private load(): ChatGptStoreDocument {
    {
      this.document = readDocument(this.file)
      if (this.document !== undefined) {
        const accounts = { ...this.document.accounts }
        let changed = false
        for (const [key, credential] of Object.entries(accounts)) {
          if (credential === null || typeof credential !== 'object') continue
          if (isReplayNamespace(credential.replayNamespace)) continue
          accounts[key] = { ...credential, replayNamespace: randomUUID() }
          changed = true
        }
        // Old subject values may have been fabricated by adopt(). Do not use
        // them to recover an identity: assign a fresh local authorization scope.
        if (changed) return this.mutate(() => {
          const latest = readDocument(this.file) ?? emptyDocument(this.hostId())
          const upgraded = Object.fromEntries(Object.entries(latest.accounts).map(([key, value]) =>
            [key, isReplayNamespace(value.replayNamespace) ? value : { ...value, replayNamespace: randomUUID() }]))
          this.save({ ...latest, accounts: upgraded })
          return this.document!
        })
      }
    }
    return this.document ?? emptyDocument(this.hostId())
  }

  /** The persisted host id, minted on first use. */
  hostId(): string {
    return ensureHostId({ file: join(dirname(this.file), 'chatgpt-host-id') })
  }

  /** Persist a complete document. */
  private save(document: ChatGptStoreDocument): void {
    writeDocument(this.file, document)
    this.document = document
  }

  /** The active grant, or `undefined` when nothing usable is stored. */
  active(): ChatGptCredential | undefined {
    const document = this.load()
    const subject = document.active
    if (subject === undefined) return undefined
    return document.accounts[subject]
  }

  /**
   * The active grant with a usable access token, refreshing first when needed.
   *
   * @param signal - cancellation for the refresh.
   * @returns the usable credential.
   * @throws {RefreshRefusedError} when the grant can no longer be refreshed.
   */
  async usable(signal?: AbortSignal): Promise<ChatGptCredential> {
    const current = this.active()
    if (current === undefined) {
      throw new Error('no ChatGPT account is signed in; run a sign-in first')
    }
    if (!canSpendPlan(current)) throw new Error('ChatGPT plan usage is disabled; authorize plan usage before inference')
    if (isFresh(current)) return current
    return this.rotate(current, signal)
  }

  /**
   * Mint a new access token from the stored grant, once, for concurrent callers.
   *
   * Rotation is single-use — the refresh token is replaced by the exchange — so
   * two callers refreshing at once would have the second present a token the
   * first already spent, and the endpoint reports that as a dead grant rather
   * than as a race.
   */
  private rotate(current: ChatGptCredential, signal?: AbortSignal): Promise<ChatGptCredential> {
    const namespace = current.replayNamespace
    if (!isReplayNamespace(namespace)) throw new Error('the stored credential has no replay namespace')
    const pending = this.refreshing.get(namespace)
    if (pending !== undefined) return pending
    const rotation = this.runRefresh(current, signal).finally(() => {
      this.refreshing.delete(namespace)
    })
    this.refreshing.set(namespace, rotation)
    return rotation
  }

  /**
   * Exchange the stored grant for a new one, whatever the local expiry says.
   *
   * A token can be refused while it still looks valid: the endpoint answers
   * `token_expired` for a grant it has invalidated server-side, and a local clock
   * comparison cannot see that. Authorization can also change under a live
   * session — an account upgrade, a workspace switch — which retires tokens the
   * local expiry still considers good. This is the method a caller uses when the
   * endpoint has just told it the token is no good.
   *
   * @param signal - cancellation for the exchange.
   * @returns the rotated credential.
   */
  async renew(signal?: AbortSignal): Promise<ChatGptCredential> {
    const current = this.active()
    if (current === undefined) {
      throw new Error('no ChatGPT account is signed in; run a sign-in first')
    }
    return this.rotate(current, signal)
  }

  /** Refresh under a cross-process file lock; another process may have rotated this grant first. */
  private async runRefresh(current: ChatGptCredential, signal?: AbortSignal): Promise<ChatGptCredential> {
    return withCredentialFileLock(`${this.file}.refresh`, async () => {
      const document = await this.mutateAsync(() => readDocument(this.file), signal)
      const key = Object.entries(document?.accounts ?? {})
        .find(([, stored]) => stored.replayNamespace === current.replayNamespace)?.[0]
      if (document === undefined || key === undefined) {
        throw new Error('the authorization was removed before refresh')
      }
      const latest = document.accounts[key]!
      if (latest.refreshToken !== current.refreshToken) {
        // A concurrent DSH process already rotated the single-use refresh token.
        this.document = document
          return latest
      }
      const timeout = AbortSignal.timeout(30_000)
      const refreshSignal = signal === undefined ? timeout : AbortSignal.any([signal, timeout])
      const rotated = await refreshCredential(latest, {
        ...this.options.endpoints?.tokenUrl === undefined ? {} : { tokenUrl: this.options.endpoints.tokenUrl },
        signal: refreshSignal,
      })
      await this.mutateAsync(() => {
        const reloaded = readDocument(this.file)
        if (reloaded === undefined || (reloaded.accounts[key]?.refreshToken !== latest.refreshToken || reloaded.accounts[key]?.replayNamespace !== latest.replayNamespace)) {
          throw new Error('the authorization changed or was removed during refresh')
        }
        this.save({ ...reloaded, accounts: { ...reloaded.accounts, [key]: rotated } })
      })
      return rotated
    }, signal)
  }

  /** Force refresh the exact authorization that received an HTTP token refusal. */
  renewFor(credential: ChatGptCredential, signal?: AbortSignal): Promise<ChatGptCredential> {
    return this.rotate(credential, signal)
  }

  /**
   * Begin a sign-in. A registration already stored for this installation is
   * reused, which is what keeps the issued client id stable across sign-ins.
   *
   * @returns the attempt, already listening for its callback.
   */
  /**
   * The registration to reuse when no credential is active.
   *
   * With one account this is that account's client, so signing out and back in
   * returns to the same registration instead of registering a second client. With
   * several, the most recently confirmed one is offered and the browser's account
   * selector still decides; the returned ID token is validated against the client
   * the attempt used, as always.
   */
  private retainedRegistration(): ChatGptRegistration | undefined {
    const registrations = this.load().registrations ?? {}
    let best: ChatGptRegistration | undefined
    for (const registration of Object.values(registrations)) {
      if (best === undefined || registration.at > best.at) best = registration
    }
    return best
  }

  async begin(): Promise<SignInAttempt> {
    const stored = this.active()
    const retained = stored === undefined ? this.retainedRegistration() : undefined
    const existing = stored ?? (retained === undefined ? undefined : {
      clientId: retained.clientId,
      email: retained.email,
    })
    const attemptOptions: SignInOptions = {
      agentHostId: this.hostId(),
      agentNameHint: this.options.agentNameHint,
      ...this.options.endpoints?.authorizeUrl === undefined ? {} : { authorizeUrl: this.options.endpoints.authorizeUrl },
      ...this.options.endpoints?.tokenUrl === undefined ? {} : { tokenUrl: this.options.endpoints.tokenUrl },
      ...this.options.endpoints?.preferredPort === undefined ? {} : { preferredPort: this.options.endpoints.preferredPort },
      ...this.options.endpoints?.verifyIdTokenSignature === undefined ? {} : { verifyIdTokenSignature: this.options.endpoints.verifyIdTokenSignature },
      // A previously issued client id skips registration entirely, which is the
      // documented path for a returning account on the same installation.
      ...existing === undefined ? {} : {
        registration: {
          clientId: existing.clientId,
          ...stored?.subject === undefined ? {} : { expectedSubject: stored.subject },
          ...existing.email === undefined ? {} : { loginHint: existing.email },
        },
      },
    }
    return beginSignIn(attemptOptions)
  }

  /**
   * Store a completed grant and make it the active account.
   *
   * @param credential - what the sign-in produced.
   * @returns the local account key the grant was filed under.
   */
  adopt(credential: ChatGptCredential): string {
    return this.mutate(() => this.adoptUnlocked(credential))
  }

  private adoptUnlocked(credential: ChatGptCredential): string {
    const document = this.load()
    const { subject, replayNamespace: _suppliedNamespace, ...rest } = credential
    const identity = typeof subject === 'string' && subject.trim().length > 0 ? subject : undefined
    const key = identity ?? `account-${randomUUID()}`
    const stored: ChatGptCredential = {
      ...rest,
      ...identity === undefined ? {} : { subject: identity },
      // Never adopt a caller-supplied namespace or reuse one after reauthorization.
      replayNamespace: randomUUID(),
    }
    this.save({
      ...document,
      accounts: { ...document.accounts, [key]: stored },
      registrations: {
        ...document.registrations ?? {},
        [key]: {
          clientId: credential.clientId,
          at: Date.now(),
          ...credential.email === undefined ? {} : { email: credential.email },
        },
      },
      active: key,
    })
    return key
  }

  /** Make an already-authorized account active. */
  activate(subject: string): void {
    return this.mutate(() => this.activateUnlocked(subject))
  }

  private activateUnlocked(subject: string): void {
    const document = this.load()
    if (document.accounts[subject] === undefined) {
      throw new Error(`no stored ChatGPT account is filed under ${subject}`)
    }
    this.save({ ...document, active: subject })
  }

  /**
   * End one account's session at the server, then forget it locally.
   *
   * Local removal alone would leave the grant redeemable at OpenAI, and nothing
   * would tell the account that this installation let go. The revocation is
   * attempted first; local state is cleared either way, because a user who asked
   * to sign out must end up signed out here even when the server cannot be
   * reached — but the outcome says which of the two happened.
   *
   * @param subject - the account to end; defaults to the active one.
   * @param options - endpoint overrides and cancellation.
   * @returns whether the server confirmed the revocation.
   */
  async revoke(subject?: string, options: RevokeOptions = {}): Promise<RevocationResult> {
    const document = this.load()
    const target = subject ?? document.active
    const credential = target === undefined ? undefined : document.accounts[target]
    if (target === undefined) return { confirmed: true }
    if (credential === undefined) {
      this.signOut(target)
      return { confirmed: false, reason: `no stored ChatGPT account is filed under ${target}` }
    }
    const result = await revokeGrant(credential, {
      ...this.options.endpoints?.revocationEndpoint === undefined
        ? {}
        : { revocationEndpoint: this.options.endpoints.revocationEndpoint },
      ...this.options.endpoints?.discoveryUrl === undefined
        ? {}
        : { discoveryUrl: this.options.endpoints.discoveryUrl },
      ...options,
    })
    this.signOut(target)
    return result
  }

  /** Forget one account, or every account when no subject is named. */
  signOut(subject?: string): void {
    return this.mutate(() => this.signOutUnlocked(subject))
  }

  private signOutUnlocked(subject?: string): void {
    const document = this.load()
    if (subject === undefined) {
      // Every credential goes; the registrations stay, because they describe the
      // account rather than the session and the next sign-in is expected to reuse
      // them. Deleting the directory is what forgets an installation entirely.
      const { active: _cleared, ...rest } = document
      this.save({ ...rest, accounts: {} })
      return
    }
    const accounts = { ...document.accounts }
    delete accounts[subject]
    const nextActive = document.active === subject
      ? Object.keys(accounts)[0]
      : document.active
    this.save({
      ...document,
      accounts,
      ...nextActive === undefined ? { active: undefined as unknown as string } : { active: nextActive },
    })
  }

  /** Account facts for the settings surface. */
  status(): ChatGptStatus {
    const document = this.load()
    const active = this.active()
    const entries = Object.entries(document.accounts)
    return {
      signedIn: active !== undefined && canSpendPlan(active),
      planUsageDenied: active !== undefined && !canSpendPlan(active),
      ...active?.email === undefined ? {} : { email: active.email },
      ...active?.planType === undefined ? {} : { plan: active.planType },
      ...active === undefined ? {} : { expiresAt: active.expiresAt },
      accounts: entries.map(([subject, credential]) => ({
        subject,
        ...credential.email === undefined ? {} : { email: credential.email },
        active: subject === document.active,
      })),
    }
  }
}

export { RefreshRefusedError }
